INSERT INTO src_locator(source_work_id,source_artifact_id,locator_type,heading_path,display_citation) SELECT a.source_work_id,a.source_artifact_id,'heading','Space Combat > Damage > Scaling Damage: Ship Weapons Against Personal-Scale Targets',CASE w.work_code WHEN 'cepheus-engine.ogn' THEN 'Cepheus Engine SRD, Space Combat: Scaling Damage' ELSE 'Cepheus Engine v9.1, Space Combat: Scaling Damage' END FROM src_artifact a JOIN src_work w USING(source_work_id) WHERE (w.work_code='cepheus-engine.ogn' AND a.source_uri LIKE '%cepheus-engine-space-combat/') OR (w.work_code='cepheus-engine.github-v9.1' AND a.source_uri='src/book2/space-combat.md') ON CONFLICT DO NOTHING;
WITH p AS(SELECT content_package_id FROM sys_content_package WHERE package_code='cepheus-engine') INSERT INTO rule_rule(content_package_id,rule_code,name,rule_category,rule_status,description) SELECT content_package_id,'combat.space.personal-scale-damage','Ship Weapons Against Personal-Scale Targets','combat','approved','Specific personal-scale targets impose DM-4 and receive the published scaled damage and radiation.' FROM p;
CREATE TABLE rule_space_combat_personal_scale_damage(rule_id bigint NOT NULL REFERENCES rule_rule(rule_id),scaling_weapon_code text NOT NULL,weapon_name text NOT NULL,weapon_rule_id bigint REFERENCES ship_weapon_definition(weapon_rule_id),missile_code text REFERENCES rule_ship_missile(missile_code),specific_target_attack_dm smallint NOT NULL CHECK(specific_target_attack_dm=-4),damage_dice_count smallint NOT NULL CHECK(damage_dice_count>0),damage_die_sides smallint NOT NULL CHECK(damage_die_sides=6),damage_multiplier smallint NOT NULL CHECK(damage_multiplier IN(1,50)),radiation_dice_count smallint NOT NULL CHECK(radiation_dice_count IN(0,4)),radiation_die_sides smallint,radiation_multiplier_rads smallint,PRIMARY KEY(rule_id,scaling_weapon_code),CHECK(num_nonnulls(weapon_rule_id,missile_code)=1),CHECK((radiation_dice_count=0)=(radiation_die_sides IS NULL)),CHECK((radiation_dice_count=0)=(radiation_multiplier_rads IS NULL)));
INSERT INTO rule_space_combat_personal_scale_damage SELECT r.rule_id,v.code,v.name,w.weapon_rule_id,v.missile_code,-4,v.damage_dice,6,v.multiplier,v.rad_dice,CASE WHEN v.rad_dice>0 THEN 6 END,CASE WHEN v.rad_dice>0 THEN 10 END FROM rule_rule r CROSS JOIN (VALUES('beam-laser','Beam Laser','beam-laser',NULL::text,1,50,0),('fusion-gun-bay','Fusion Gun (bay)','fusion-gun-bay',NULL,5,50,0),('meson-gun-bay','Meson Gun (bay)','meson-gun-bay',NULL,5,50,4),('nuclear-missile','Nuclear Missile',NULL,'nuclear',2,50,4),('particle-beam-bay','Particle Beam (bay)','particle-beam-bay',NULL,6,50,4),('particle-beam-turret','Particle Beam (turret)','particle-beam-turret',NULL,3,50,4),('pulse-laser','Pulse Laser','pulse-laser',NULL,2,50,0),('sandcaster','Sandcaster','sandcaster',NULL,8,1,0),('smart-missile','Smart Missile',NULL,'smart',1,50,0),('standard-missile','Standard Missile',NULL,'standard',1,50,0)) v(code,name,weapon_code,missile_code,damage_dice,multiplier,rad_dice) LEFT JOIN ship_weapon_definition w ON w.weapon_code=v.weapon_code WHERE r.rule_code='combat.space.personal-scale-damage';
INSERT INTO src_record_provenance(rule_id,content_package_id,source_locator_id,provenance_class,is_primary_citation) SELECT r.rule_id,r.content_package_id,l.source_locator_id,CASE w.work_code WHEN 'cepheus-engine.ogn' THEN 'direct' ELSE 'corroborating' END,w.work_code='cepheus-engine.ogn' FROM rule_rule r CROSS JOIN src_locator l JOIN src_work w USING(source_work_id) WHERE r.rule_code='combat.space.personal-scale-damage' AND l.heading_path='Space Combat > Damage > Scaling Damage: Ship Weapons Against Personal-Scale Targets' AND w.work_code IN('cepheus-engine.ogn','cepheus-engine.github-v9.1');

CREATE TABLE senc_personal_scale_attack_receipt(personal_scale_attack_receipt_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,action_id bigint NOT NULL UNIQUE,space_combat_round_id bigint NOT NULL,engagement_id bigint NOT NULL,campaign_id bigint NOT NULL,attacker_vessel_id bigint NOT NULL,gunner_assignment_id bigint NOT NULL,gunner_ship_id bigint NOT NULL,target_actor_id bigint NOT NULL,scaling_weapon_code text NOT NULL,weapon_rule_id bigint REFERENCES ship_weapon_definition(weapon_rule_id),missile_code text REFERENCES rule_ship_missile(missile_code),task_command_id bigint NOT NULL UNIQUE REFERENCES cmd_actor_task_receipt(command_id),task_effect smallint NOT NULL,hit boolean NOT NULL,recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),FOREIGN KEY(action_id,engagement_id,campaign_id) REFERENCES senc_action(space_combat_action_id,engagement_id,campaign_id),FOREIGN KEY(space_combat_round_id,engagement_id,campaign_id) REFERENCES senc_round(space_combat_round_id,engagement_id,campaign_id),FOREIGN KEY(attacker_vessel_id,engagement_id,campaign_id) REFERENCES senc_vessel(senc_vessel_id,engagement_id,campaign_id),FOREIGN KEY(gunner_assignment_id,gunner_ship_id,campaign_id) REFERENCES ship_crew_assignment(crew_assignment_id,ship_id,campaign_id),FOREIGN KEY(target_actor_id,campaign_id) REFERENCES actor_actor(actor_id,campaign_id),CHECK(num_nonnulls(weapon_rule_id,missile_code)=1));
CREATE TABLE senc_personal_scale_damage_die(personal_scale_attack_receipt_id bigint NOT NULL REFERENCES senc_personal_scale_attack_receipt(personal_scale_attack_receipt_id),damage_kind text NOT NULL CHECK(damage_kind IN('normal','radiation')),die_order smallint NOT NULL CHECK(die_order>0),result smallint NOT NULL CHECK(result BETWEEN 1 AND 6),PRIMARY KEY(personal_scale_attack_receipt_id,damage_kind,die_order));
CREATE TABLE senc_personal_scale_damage_receipt(personal_scale_attack_receipt_id bigint PRIMARY KEY REFERENCES senc_personal_scale_attack_receipt(personal_scale_attack_receipt_id),target_actor_id bigint NOT NULL,normal_rolled_total smallint NOT NULL CHECK(normal_rolled_total>0),normal_damage integer NOT NULL CHECK(normal_damage>0),radiation_rolled_total smallint NOT NULL CHECK(radiation_rolled_total>=0),radiation_rads integer NOT NULL CHECK(radiation_rads>=0),damage_instance_id bigint UNIQUE,radiation_exposure_id bigint UNIQUE,recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK((radiation_rolled_total=0)=(radiation_rads=0)));

CREATE FUNCTION senc_validate_personal_scale_attack() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE a record;t cmd_actor_task_receipt%ROWTYPE;profile record;skill_code text;BEGIN SELECT action.action_code,action.space_combat_round_id,turn.senc_vessel_id,turn.crew_assignment_id,assignment.ship_id,assignment.actor_id,assignment.duty_status INTO STRICT a FROM senc_action action JOIN senc_crew_turn turn USING(crew_turn_id) JOIN ship_crew_assignment assignment USING(crew_assignment_id) WHERE action.space_combat_action_id=NEW.action_id;SELECT * INTO STRICT t FROM cmd_actor_task_receipt WHERE command_id=NEW.task_command_id;SELECT p.*,w.weapon_kind INTO STRICT profile FROM rule_space_combat_personal_scale_damage p JOIN rule_rule r ON r.rule_id=p.rule_id LEFT JOIN ship_weapon_definition w ON w.weapon_rule_id=p.weapon_rule_id WHERE r.rule_code='combat.space.personal-scale-damage' AND p.scaling_weapon_code=NEW.scaling_weapon_code;SELECT rule_code INTO STRICT skill_code FROM rule_rule WHERE rule_id=t.skill_rule_id;
 IF a.action_code<>'attack' OR a.space_combat_round_id<>NEW.space_combat_round_id OR a.senc_vessel_id<>NEW.attacker_vessel_id OR a.crew_assignment_id<>NEW.gunner_assignment_id OR a.ship_id<>NEW.gunner_ship_id OR a.actor_id<>t.actor_id OR a.duty_status<>'active' OR NEW.weapon_rule_id IS DISTINCT FROM profile.weapon_rule_id OR NEW.missile_code IS DISTINCT FROM profile.missile_code OR t.circumstance_modifier<>-4 OR t.effect<>NEW.task_effect OR t.succeeded<>NEW.hit OR skill_code NOT IN('skill.turret-weapons','skill.bay-weapons') OR (NEW.weapon_rule_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM ship_ship ship JOIN ship_class_weapon class_weapon USING(ship_class_rule_id) WHERE ship.ship_id=NEW.gunner_ship_id AND class_weapon.weapon_rule_id=NEW.weapon_rule_id)) THEN RAISE EXCEPTION 'Personal-scale ship attack must match its active gunner, installed weapon or missile, DM-4 check, and published profile' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER senc_personal_scale_attack_valid BEFORE INSERT ON senc_personal_scale_attack_receipt FOR EACH ROW EXECUTE FUNCTION senc_validate_personal_scale_attack();
CREATE FUNCTION senc_validate_personal_scale_die() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE p record;BEGIN SELECT profile.damage_dice_count,profile.radiation_dice_count,attack.hit INTO STRICT p FROM senc_personal_scale_attack_receipt attack JOIN rule_rule r ON r.rule_code='combat.space.personal-scale-damage' JOIN rule_space_combat_personal_scale_damage profile ON profile.rule_id=r.rule_id AND profile.scaling_weapon_code=attack.scaling_weapon_code WHERE attack.personal_scale_attack_receipt_id=NEW.personal_scale_attack_receipt_id;IF NOT p.hit OR EXISTS(SELECT 1 FROM senc_personal_scale_damage_receipt WHERE personal_scale_attack_receipt_id=NEW.personal_scale_attack_receipt_id) OR NEW.die_order>(CASE NEW.damage_kind WHEN 'normal' THEN p.damage_dice_count ELSE p.radiation_dice_count END) THEN RAISE EXCEPTION 'Personal-scale damage die exceeds its unresolved published profile' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER senc_personal_scale_die_valid BEFORE INSERT ON senc_personal_scale_damage_die FOR EACH ROW EXECUTE FUNCTION senc_validate_personal_scale_die();

ALTER TABLE health_damage_instance ADD COLUMN personal_scale_attack_receipt_id bigint UNIQUE REFERENCES senc_personal_scale_attack_receipt(personal_scale_attack_receipt_id);
ALTER TABLE health_damage_instance DROP CONSTRAINT health_damage_exactly_one_source_check,ADD CONSTRAINT health_damage_exactly_one_source_check CHECK(num_nonnulls(attack_command_id,environmental_command_id,explosion_command_id,grapple_option_command_id,personal_scale_attack_receipt_id)+CASE WHEN crew_damage_location_hit_receipt_id IS NULL THEN 0 ELSE 1 END+CASE WHEN missile_crew_hit_receipt_id IS NULL THEN 0 ELSE 1 END=1);
ALTER TABLE health_radiation_exposure ADD COLUMN personal_scale_attack_receipt_id bigint UNIQUE REFERENCES senc_personal_scale_attack_receipt(personal_scale_attack_receipt_id);
ALTER TABLE health_radiation_exposure DROP CONSTRAINT health_radiation_one_crew_origin,ADD CONSTRAINT health_radiation_one_origin CHECK(num_nonnulls(damage_location_hit_receipt_id,missile_crew_hit_receipt_id,personal_scale_attack_receipt_id)=1);
ALTER TABLE senc_personal_scale_damage_receipt ADD CONSTRAINT senc_personal_scale_damage_instance_fk FOREIGN KEY(damage_instance_id) REFERENCES health_damage_instance(damage_instance_id),ADD CONSTRAINT senc_personal_scale_radiation_exposure_fk FOREIGN KEY(radiation_exposure_id) REFERENCES health_radiation_exposure(radiation_exposure_id);
CREATE FUNCTION senc_finalize_personal_scale_damage() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE attack senc_personal_scale_attack_receipt%ROWTYPE;profile rule_space_combat_personal_scale_damage%ROWTYPE;normal_n integer;normal_total integer;rad_n integer;rad_total integer;damage_id bigint;exposure_id bigint;state actor_radiation_state%ROWTYPE;BEGIN SELECT * INTO STRICT attack FROM senc_personal_scale_attack_receipt WHERE personal_scale_attack_receipt_id=NEW.personal_scale_attack_receipt_id FOR UPDATE;SELECT p.* INTO STRICT profile FROM rule_space_combat_personal_scale_damage p JOIN rule_rule r ON r.rule_id=p.rule_id WHERE r.rule_code='combat.space.personal-scale-damage' AND p.scaling_weapon_code=attack.scaling_weapon_code;SELECT count(*) FILTER(WHERE damage_kind='normal'),coalesce(sum(result) FILTER(WHERE damage_kind='normal'),0),count(*) FILTER(WHERE damage_kind='radiation'),coalesce(sum(result) FILTER(WHERE damage_kind='radiation'),0) INTO normal_n,normal_total,rad_n,rad_total FROM senc_personal_scale_damage_die WHERE personal_scale_attack_receipt_id=NEW.personal_scale_attack_receipt_id;
 IF NOT attack.hit OR NEW.target_actor_id<>attack.target_actor_id OR normal_n<>profile.damage_dice_count OR rad_n<>profile.radiation_dice_count OR NEW.normal_rolled_total<>normal_total OR NEW.normal_damage<>normal_total*profile.damage_multiplier OR NEW.radiation_rolled_total<>rad_total OR NEW.radiation_rads<>rad_total*coalesce(profile.radiation_multiplier_rads,0) THEN RAISE EXCEPTION 'Personal-scale damage receipt fails hit, complete dice, multiplier, or radiation recomputation' USING ERRCODE='23514';END IF;
 INSERT INTO health_damage_instance(target_actor_id,penetrating_damage,personal_scale_attack_receipt_id) VALUES(attack.target_actor_id,NEW.normal_damage,attack.personal_scale_attack_receipt_id) RETURNING damage_instance_id INTO damage_id;NEW.damage_instance_id:=damage_id;
 IF NEW.radiation_rads>0 THEN INSERT INTO actor_radiation_state(actor_id,campaign_id) VALUES(attack.target_actor_id,attack.campaign_id) ON CONFLICT(actor_id) DO NOTHING;SELECT * INTO STRICT state FROM actor_radiation_state WHERE actor_id=attack.target_actor_id FOR UPDATE;UPDATE actor_radiation_state SET total_rads=state.total_rads+NEW.radiation_rads,concurrency_version=state.concurrency_version+1,updated_at=clock_timestamp() WHERE actor_id=state.actor_id;INSERT INTO health_radiation_exposure(personal_scale_attack_receipt_id,actor_id,campaign_id,rads_added,rads_before,rads_after,actor_radiation_version_before,actor_radiation_version_after) VALUES(attack.personal_scale_attack_receipt_id,attack.target_actor_id,attack.campaign_id,NEW.radiation_rads,state.total_rads,state.total_rads+NEW.radiation_rads,state.concurrency_version,state.concurrency_version+1) RETURNING radiation_exposure_id INTO exposure_id;NEW.radiation_exposure_id:=exposure_id;END IF;RETURN NEW;END $$;
CREATE TRIGGER senc_personal_scale_damage_final BEFORE INSERT ON senc_personal_scale_damage_receipt FOR EACH ROW EXECUTE FUNCTION senc_finalize_personal_scale_damage();
CREATE FUNCTION senc_reject_personal_scale_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Personal-scale ship-weapon attack and damage receipts are immutable';END $$;CREATE TRIGGER senc_personal_scale_attack_immutable BEFORE UPDATE OR DELETE ON senc_personal_scale_attack_receipt FOR EACH ROW EXECUTE FUNCTION senc_reject_personal_scale_mutation();CREATE TRIGGER senc_personal_scale_die_immutable BEFORE UPDATE OR DELETE ON senc_personal_scale_damage_die FOR EACH ROW EXECUTE FUNCTION senc_reject_personal_scale_mutation();CREATE TRIGGER senc_personal_scale_damage_immutable BEFORE UPDATE OR DELETE ON senc_personal_scale_damage_receipt FOR EACH ROW EXECUTE FUNCTION senc_reject_personal_scale_mutation();
